(async () => {
  const out = {};
  ['#top-picks','#factory','#cases','#catalogue','#journal'].forEach(s => {
    const el = document.querySelector(s); out[s] = el ? Math.round(el.offsetHeight) : null;
  });
  out.doc = document.body.scrollHeight;
  out.swipes = document.querySelectorAll('.swipe').length;
  out.dots = document.querySelectorAll('.swipe-dots').length;
  out.docW = document.documentElement.scrollWidth;
  // open the modal and measure it
  document.querySelector('[data-quote-open]').click();
  await new Promise(r => setTimeout(r, 400));
  const m = document.getElementById('gquote');
  const p = m.querySelector('.gquote__panel');
  const r = p.getBoundingClientRect();
  out.modal = {x: Math.round(r.x), w: Math.round(r.width), vw: innerWidth, overflow: r.right > innerWidth + 1};
  const cols = getComputedStyle(p).gridTemplateColumns;
  out.modalCols = cols;
  const cut = [...m.querySelectorAll('.gquote__points li')].map(li => li.scrollWidth > li.clientWidth + 1);
  out.pointsClipped = cut;
  return out;
})()
